export const catalog=[
['sofa','Sofa',2.2,.9,.85,'#a9a39a'],['chair','Stuhl',.48,.55,.9,'#9d714c'],['armchair','Sessel',.85,.85,.9,'#748d83'],['table','Esstisch',1.6,.85,.75,'#ac8057'],['coffee','Couchtisch',.9,.55,.45,'#ac8057'],['bed','Doppelbett',1.8,2.05,.85,'#b7a99a'],['single','Einzelbett',.9,2,.8,'#839eaa'],['wardrobe','Schrank',1.5,.6,2.1,'#d8d2c6'],['cabinet','Kommode',1,.45,.85,'#b58e65'],['kitchen','Küchenmodul',.6,.6,.9,'#d6d8d6'],['fridge','Kühlschrank',.65,.65,1.9,'#b6c0c6'],['sink','Spülenschrank',.8,.6,.9,'#ddd9d0'],['toilet','WC',.4,.7,.78,'#f3f3f0'],['bath','Badewanne',.8,1.7,.58,'#f3f3f0'],['shower','Dusche',.9,.9,2,'#a7ced5'],['desk','Schreibtisch',1.2,.65,.75,'#b68c64'],['plant','Pflanze',.55,.55,1.1,'#518454'],['lamp','Stehlampe',.4,.4,1.65,'#d0a35d'],['rug','Teppich',2,1.4,.03,'#acb7ad'],['tv','Fernseher',1.2,.12,.75,'#252b30'],['stair','Gerade Treppe',1,3.8,2.7,'#ab8965'],['pool','Pool',3,5,.3,'#51abc9']].map(([kind,name,width,depth,height,color])=>({kind,name,width,depth,height,color}));
export function object(kind,p){const c=catalog.find(c=>(c.modelId||c.kind)===kind);if(!c)throw Error('Unbekanntes Objekt');return {...c,id:uid(),...p,rotation:0,elevation:0}}

const cross=(a,b)=>a.x*b.y-a.y*b.x;
const sub=(a,b)=>({x:a.x-b.x,y:a.y-b.y});
const mix=(a,b,t)=>({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});
const EPS=1e-7;
// Non-destructive planar graph: split at crossings and T-junctions for face tracing.
export function topology(walls){const cuts=walls.map(()=>[0,1]);const push=(i,t)=>{if(t>EPS&&t<1-EPS)cuts[i].push(t)};
for(let i=0;i<walls.length;i++)for(let j=i+1;j<walls.length;j++){const a=walls[i],b=walls[j],u=sub(a.b,a.a),v=sub(b.b,b.a),w=sub(b.a,a.a),d=cross(u,v);if(Math.abs(d)>EPS){const t=cross(w,v)/d,s=cross(w,u)/d;if(t>=-EPS&&t<=1+EPS&&s>=-EPS&&s<=1+EPS){push(i,t);push(j,s)}}else if(Math.abs(cross(w,u))<EPS){for(const q of [b.a,b.b]){const n=projection(q,a);if(n.d<EPS)push(i,n.t/n.L)}for(const q of [a.a,a.b]){const n=projection(q,b);if(n.d<EPS)push(j,n.t/n.L)}}}
const out=[],seen=new Set();walls.forEach((w,i)=>{const ts=[...new Set(cuts[i].map(t=>Math.round(t*1e9)/1e9))].sort((a,b)=>a-b);for(let j=1;j<ts.length;j++){const a=mix(w.a,w.b,ts[j-1]),b=mix(w.a,w.b,ts[j]);if(dist(a,b)<EPS)continue;const k=[key(a),key(b)].sort().join('|');if(seen.has(k))continue;seen.add(k);out.push({...w,a,b})}});return out}
export function insertWall(l,a,b){const w=wall(a,b,.2,l.height),u=sub(b,a);for(const old of l.walls){const v=sub(old.b,old.a);if(Math.abs(cross(u,v))<EPS&&Math.abs(cross(sub(old.a,a),u))<EPS){const dot=q=>((q.x-a.x)*u.x+(q.y-a.y)*u.y)/(u.x*u.x+u.y*u.y);const t=[dot(old.a),dot(old.b)].sort((x,y)=>x-y);if(Math.min(1,t[1])-Math.max(0,t[0])>EPS)throw Error('Wand überlappt eine vorhandene Wand')}}l.walls.push(w);return w}
export const materials=[['oak','Eiche','#c6a475'],['walnut','Nussbaum','#75533b'],['tile','Fliesen','#c9ced0'],['marble','Marmor','#e5e1db'],['concrete','Beton','#a3a5a3'],['carpet','Teppich','#a8aba0'],['grass','Rasen','#749457'],['slate','Schiefer','#62696e']].map(([id,name,color])=>({id,name,color}));
export const materialColor=id=>materials.find(m=>m.id===id)?.color||materials[0].color;
export function contains(poly,p){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)yes=!yes}return yes}
export function footprint(o){const a=o.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a);return [[-1,-1],[1,-1],[1,1],[-1,1]].map(([x,y])=>({x:o.x+x*o.width/2*c-y*o.depth/2*s,y:o.y+x*o.width/2*s+y*o.depth/2*c}))}
export function stairLinks(p){const out=[];for(const l of p.levels){const upper=p.levels.filter(q=>q.z>l.z+.1).sort((a,b)=>a.z-b.z)[0];if(!upper)continue;for(const o of l.objects.filter(isStair)){const poly=footprint(o),r=rooms(upper).find(r=>poly.every(q=>contains(r.points,q)));if(r)out.push({lower:l.id,upper:upper.id,room:r.id,polygon:poly,object:o,rise:upper.z-l.z})}}return out}
export function template(type,name){if(type.startsWith('preset-'))return presetProject(type,name);if(type.startsWith('room-'))return roomTemplate(type,name);const p=project(name),l=p.levels[0],P=(x,y)=>({x,y});if(type==='empty')return p;const w=type==='studio'?6:type==='family'?12:9,h=type==='studio'?5:8;rectangle(l,P(0,0),P(w,h));if(type!=='studio'){insertWall(l,P(w*.6,0),P(w*.6,h));insertWall(l,P(w*.6,h/2),P(w,h/2));addOpening(l.walls[4],h*.25,'door');addOpening(l.walls[4],h*.75,'door')}addOpening(l.walls[0],w*.25,'window');addOpening(l.walls[2],w*.25,'door');l.objects.push(object('sofa',P(2,1.2)),object('coffee',P(2,2.2)),object('bed',P(w-1.4,h-1.5)),object('plant',P(.7,.7)));if(type==='family'){const u=level('Obergeschoss',2.7);rectangle(u,P(0,0),P(w,h));insertWall(u,P(w/2,0),P(w/2,h));addOpening(u.walls[4],h/2,'door');p.levels.push(u);l.objects.push({...object('stair',P(4,5)),height:2.7});p.roof='gable'}return p}

export function localPoint(o,p){const a=o.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a),x=p.x-o.x,y=p.y-o.y;return{x:x*c+y*s,y:-x*s+y*c}}
export function stairHeight(link,p){const q=localPoint(link.object,p);for(const s of stairSteps(link.object,link.rise))if(contains(s.polygon,q))return s.height;return null}
export function walkTarget(p,lid,from,to){const l=p.levels.find(q=>q.id===lid);if(!l)return null;const links=stairLinks(p).filter(a=>a.lower===lid||a.upper===lid);let floor=l.z,next=lid;const foot=from.height;let on=false;
for(const a of links){const low=p.levels.find(q=>q.id===a.lower),z=stairHeight(a,to),previous=stairHeight(a,from);if(z!==null){const target=low.z+z;if(Math.abs(foot-target)>.46)return null;floor=target;next=a.lower;on=true;break}if(previous!==null){const q=localPoint(a.object,to);if((a.object.kind==='stair'?q.y>a.object.depth/2:stairPortal(a,to,true))&&Math.abs(foot-(low.z+a.rise))<.46){floor=low.z+a.rise;next=a.upper;break}if((a.object.kind==='stair'?q.y< -a.object.depth/2:stairPortal(a,to,false))&&Math.abs(foot-low.z)<.46){floor=low.z;next=a.lower;break}return null}}
if(!on&&Math.abs(floor-foot)>.46)return null;const target=p.levels.find(q=>q.id===next);if(target.walls.some(w=>{const q=projection(to,w);return q.d<w.thickness/2+.13&&!w.openings.some(o=>o.type==='door'&&o.open&&Math.abs(o.t-q.t)<o.width/2-.1)}))return null;
if(target.objects.some(o=>{if(o.hidden||isStair(o)||['rug','pool'].includes(o.kind)||o.elevation>1.8||o.height<.12)return false;const q=localPoint(o,to);return Math.abs(q.x)<o.width/2+.12&&Math.abs(q.y)<o.depth/2+.12}))return null;
return {level:next,height:floor}}

