const variants=[['Eiche','#b68b5d',1],['Nussbaum','#76543e',1],['Weiss','#e6e5df',1],['Anthrazit','#454b50',1],['Salbei','#819687',1],['Sand','#d1bda5',1],['Kompakt','#a3a8a5',.8],['Gross','#ac9277',1.2]];
