export function quantities(p){const result=[];for(const l of p.levels){const r=rooms(l);let wallArea=0,wallVolume=0,doors=0,windows=0;for(const w of l.walls){const a=dist(w.a,w.b)*w.height-w.openings.reduce((s,o)=>s+o.width*o.height,0);wallArea+=a;wallVolume+=a*w.thickness;for(const o of w.openings)o.type==='door'?doors++:windows++}result.push({name:l.name,floor:r.reduce((s,r)=>s+r.area,0),wallArea:wallArea*2,wallVolume,doors,windows,objects:l.objects.length})}return result}
export function roofProfile(type,w,d,pitch){const rise=w/2*Math.tan(pitch*Math.PI/180);const a=[[-w/2,0,-d/2],[w/2,0,-d/2],[w/2,0,d/2],[-w/2,0,d/2]];if(type==='flat')return {vertices:a,faces:[[0,3,2,1]]};if(type==='pyramid'){const h=Math.min(w,d)/2*Math.tan(pitch*Math.PI/180);return {vertices:[...a,[0,h,0]],faces:[[0,3,4],[3,2,4],[2,1,4],[1,0,4]]}}if(type==='shed')return {vertices:a.map((v,i)=>[v[0],i===1||i===2?rise*2:0,v[2]]),faces:[[0,3,2,1]]};if(type==='butterfly'){return {vertices:[...a.map(v=>[v[0],rise,v[2]]),[0,0,-d/2],[0,0,d/2]],faces:[[0,3,5,4],[4,5,2,1]]}}if(type==='hip'){const h=Math.min(w,d)/2*Math.tan(pitch*Math.PI/180);if(Math.abs(w-d)<1e-7)return {vertices:[...a,[0,h,0]],faces:[[0,3,4],[3,2,4],[2,1,4],[1,0,4]]};if(d>w){const z=(d-w)/2;return {vertices:[...a,[0,h,-z],[0,h,z]],faces:[[0,3,5,4],[4,5,2,1],[0,4,1],[3,2,5]]}}const x=(w-d)/2;return {vertices:[...a,[-x,h,0],[x,h,0]],faces:[[0,4,5,1],[3,2,5,4],[0,3,4],[1,5,2]]}}if(type==='mansard'){const u=w*.25,v=rise*.75;return {vertices:[...a,[-u,v,-d/2],[-u,v,d/2],[u,v,-d/2],[u,v,d/2],[0,rise,-d/2],[0,rise,d/2]],faces:[[0,3,5,4],[4,5,9,8],[8,9,7,6],[6,7,2,1]]}}return {vertices:[...a,[0,rise,-d/2],[0,rise,d/2]],faces:[[0,3,5,4],[4,5,2,1]]}}
export function curvePoints(a,b,c,segments=16){if(dist(a,b)<.05||dist(b,c)<.05)throw Error('Kurve zu kurz');return Array.from({length:segments+1},(_,i)=>{const t=i/segments,u=1-t;return{x:u*u*a.x+2*u*t*b.x+t*t*c.x,y:u*u*a.y+2*u*t*b.y+t*t*c.y}})}

const presetFamilies=[['Bungalow',10,8,1],['Stadtvilla',12,9,2],['Reihenhaus',6,11,2],['Chalet',9,8,2],['Tiny House',5,4,1],['Loft',11,8,1],['Familienwohnung',10,9,1],['Gartenhaus',5,5,1],['Büro',9,7,1],['Doppelhaushälfte',8,10,2]];
const styles=[['Kompakt',.85,'flat'],['Klassisch',1,'gable'],['Modern',1.1,'shed'],['Gross',1.25,'hip'],['Offen',1.15,'flat'],['Schmal',.9,'mansard']];
export const templateChoices=presetFamilies.flatMap(([name,w,d,levels],i)=>styles.map(([style,scale,roof],j)=>({id:'preset-'+i+'-'+j,name:name+' · '+style,w:Math.round(w*scale*10)/10,d:Math.round(d*(j===5?1.25:scale)*10)/10,levels,roof,open:j===4,family:i})));
function presetProject(id,name){const t=templateChoices.find(x=>x.id===id);if(!t)throw Error('Unbekannte Vorlage');const p=project(name),P=(x,y)=>({x,y});for(let i=0;i<t.levels;i++){const l=i===0?p.levels[0]:level('Obergeschoss '+i,i*2.7);if(i)p.levels.push(l);rectangle(l,P(0,0),P(t.w,t.d));addOpening(l.walls[0],t.w*.25,'window',Math.min(1.2,t.w*.3));if(i===0)addOpening(l.walls[2],t.w*.25,'door',.8);if(!t.open&&t.w>=6){insertWall(l,P(t.w*.6,0),P(t.w*.6,t.d));addOpening(l.walls[4],t.d*.5,'door',.8);if(t.d>7){insertWall(l,P(t.w*.6,t.d*.5),P(t.w,t.d*.5));addOpening(l.walls[5],t.w*.2,'door',.7)}}if(i===0){l.objects.push(object(t.family===8?'desk':'sofa',P(t.w*.26,t.d*.24)),object('plant',P(.65,.65)));if(t.w>=7)l.objects.push(object('coffee',P(t.w*.26,t.d*.45)))}else l.objects.push(object('bed',P(t.w*.25,t.d*.25)))}p.roof=t.roof;p.land=[0,1,3,7].includes(t.family);if(t.levels>1){const l=p.levels[0],x=t.w*.28,y=t.d*.65,depth=Math.min(3.5,t.d*.5);l.objects.push({...object('stair',P(x,y)),depth,height:2.7})}return p}

export function editWall(l,w,changes){const oldA={...w.a},oldB={...w.b},newA=changes.a||w.a,newB=changes.b||w.b;if(dist(newA,newB)<.05)throw Error('Wand ist zu kurz');for(const other of l.walls){if(other===w)continue;for(const end of ['a','b']){if(dist(other[end],oldA)<1e-5)other[end]={...newA};else if(dist(other[end],oldB)<1e-5)other[end]={...newB}}}Object.assign(w,changes);for(const other of l.walls)if(dist(other.a,other.b)<.05)throw Error('Verbundene Wand wäre zu kurz')}
export function angleSnap(a,b,increment=15){const d=dist(a,b),angle=Math.atan2(b.y-a.y,b.x-a.x),step=increment*Math.PI/180,t=Math.round(angle/step)*step;return{x:a.x+Math.cos(t)*d,y:a.y+Math.sin(t)*d}}
export function catalogStats(){return {base:catalog.filter(c=>!c.modelId).length,entries:catalog.length,variants:catalog.filter(c=>c.modelId).length}}

