export function finish(id){const m=materials.find(m=>m.id===id)||materials[0];return {...m,pattern:m.pattern||m.id,roughness:m.roughness??(['marble','tile'].includes(m.id)?.45:.82),metalness:m.metalness||0}}
export function rotatedPoint(origin,x,y,degrees=0){const a=degrees*Math.PI/180;return{x:origin.x+x*Math.cos(a)-y*Math.sin(a),y:origin.y+x*Math.sin(a)+y*Math.cos(a)}}
export function kitchenLayout(origin,{shape='straight',length=3,side=2,rotation=0,upper=true}={}){if(!['straight','L','U','island'].includes(shape)||length<1.2||length>8||side<1.2||side>6)throw Error('Ungültige Küchenmasse');const out=[],groupId=uid();const put=(kind,x,y,w,d,h,e=0,rot=0,name)=>{const o=object(kind,rotatedPoint(origin,x,y,rotation));Object.assign(o,{width:w,depth:d,height:h,elevation:e,rotation:rotation+rot,groupId});if(name)o.name=name;out.push(o)};const run=(x,y,len,rot,main)=>{const count=Math.max(2,Math.round(len/.6)),w=len/count;for(let i=0;i<count;i++){const p=rotatedPoint({x,y},(i+.5)*w,0,rot);put(main&&i===0?'sink':'kitchen',p.x,p.y,w,.6,.9,0,rot);if(upper&&i!==0)put('upper',p.x,p.y-.125,w,.35,.72,1.45,rot)}const p=rotatedPoint({x,y},len/2,0,rot);put('patio',p.x,p.y,len,.65,.04,.9,rot,'Arbeitsplatte')};run(0,0,length,0,true);if(shape==='L'||shape==='U')run(length-.3,.65,side,90,false);if(shape==='U')run(.3,.65,side,90,false);if(shape==='island')put('island',length/2,1.8,Math.min(2.4,length),.9,.92);return out}
export function bathroomLayout(origin,{width=3,depth=2.5,rotation=0,bath=false}={}){if(width<2.2||depth<2||width>10||depth>10)throw Error('Bad benötigt mindestens 2.2 × 2 m');const groupId=uid(),out=[];const put=(kind,x,y,rot=0)=>{const o=object(kind,rotatedPoint(origin,x,y,rotation));o.rotation=rotation+rot;o.groupId=groupId;out.push(o);return o};put('toilet',.4,.4);put('basin',width-.48,.35);const mirror=put('mirror',width-.48,.12);mirror.elevation=1.15;put(bath?'bath':'shower',width-.55,depth-.9);return out}
export function overlap(a,b){if((a.elevation||0)+a.height<=(b.elevation||0)||(b.elevation||0)+b.height<=(a.elevation||0))return false;const A=footprint(a),B=footprint(b);for(const poly of [A,B])for(let i=0;i<4;i++){const u=poly[i],v=poly[(i+1)%4],axis={x:-(v.y-u.y),y:v.x-u.x};const project=p=>p.map(q=>q.x*axis.x+q.y*axis.y);const x=project(A),y=project(B);if(Math.max(...x)<=Math.min(...y)+1e-7||Math.max(...y)<=Math.min(...x)+1e-7)return false}return true}
export function roomCosts(p,rates){return quantities(p).map(q=>({...q,cost:q.floor*(1+(rates.waste||0)/100)*(rates.floor||0)+q.floor*(rates.labor||0)+q.wallArea*(rates.paint||0)+q.doors*(rates.door||0)+q.windows*(rates.window||0)}))}

export const systems=[{id:'electric',name:'Elektro',color:'#d5a323'},{id:'water',name:'Kaltwasser',color:'#337ec5'},{id:'hot',name:'Warmwasser',color:'#d54b46'},{id:'drain',name:'Abwasser',color:'#766a61'},{id:'heat',name:'Heizung',color:'#d67c35'},{id:'vent',name:'Lüftung',color:'#608c79'}];
export const systemColor=id=>systems.find(s=>s.id===id)?.color||'#666666';
export function addRoute(l,system,points,elevation=0){if(!systems.some(s=>s.id===system)||points.length<2||points.length>200||points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)))throw Error('Ungültige Leitung');const length=points.slice(1).reduce((n,p,i)=>n+dist(points[i],p),0);if(length<.05)throw Error('Leitung zu kurz');const route={id:uid(),system,points:copy(points),elevation,length};(l.routes??=[]).push(route);return route}
export const landscapeTypes=[['grass','Rasen'],['gravel','Kies'],['tile','Pflaster'],['oak','Holzterrasse'],['concrete','Beton'],['water','Wasser']];
export function polygonValid(points){if(!Array.isArray(points)||points.length<3||points.length>200||points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y))||Math.abs(area(points))<.05)return false;for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if(dist(a,b)<.02)return false;for(let j=i+2;j<points.length;j++){if(i===0&&j===points.length-1)continue;const c=points[j],d=points[(j+1)%points.length],u=sub(b,a),v=sub(d,c),w=sub(c,a),den=cross(u,v);if(Math.abs(den)<EPS){if(Math.abs(cross(w,u))<EPS&&(projection(c,{a,b}).d<EPS||projection(d,{a,b}).d<EPS||projection(a,{a:c,b:d}).d<EPS))return false;continue}const t=cross(w,v)/den,k=cross(w,u)/den;if(t>=-EPS&&t<=1+EPS&&k>=-EPS&&k<=1+EPS)return false}}return true}
export function addLandscape(p,kind,points,elevation=0){points=normalizePolygon(points);if(!landscapeTypes.some(x=>x[0]===kind)||!polygonValid(points)||!Number.isFinite(elevation)||elevation< -20||elevation>20)throw Error('Fläche muss ein gültiges geschlossenes Polygon sein');const item={id:uid(),kind,points:copy(points),elevation};(p.landscape??=[]).push(item);return item}
