export function stairSteps(o,rise=o.height){const w=o.width,d=o.depth,n=Math.max(8,Math.min(60,Math.round(rise/.18))),out=[];const put=poly=>out.push({polygon:poly,height:rise*(out.length+1)/n});const run=(count,x0,y0,x1,y1,wide)=>{const dx=(x1-x0)/count,dy=(y1-y0)/count;for(let i=0;i<count;i++){const x=x0+i*dx,y=y0+i*dy;if(Math.abs(dx)>Math.abs(dy))put(rectPoly(Math.min(x,x+dx),y-wide/2,Math.max(x,x+dx),y+wide/2));else put(rectPoly(x-wide/2,Math.min(y,y+dy),x+wide/2,Math.max(y,y+dy)))}};if(o.kind==='stairL'){const a=Math.floor((n-1)/2),q=Math.min(w,d)*.34,x=-w/2+q/2,y=d/2-q/2;run(a,x,-d/2,x,y-q/2,q);put(rectPoly(-w/2,y-q/2,-w/2+q,y+q/2));run(n-a-1,-w/2+q,y,w/2,y,q)}else if(o.kind==='stairU'){const a=Math.floor((n-1)/2),q=w*.47,y=d/2-Math.min(d*.3,q),x=-w/2+q/2,X=w/2-q/2;run(a,x,-d/2,x,y,q);put(rectPoly(-w/2,y,w/2,d/2));run(n-a-1,X,y,X,-d/2,q)}else if(o.kind==='stairSpiral'){const radius=Math.min(w,d)/2,inner=radius*.13;for(let i=0;i<n;i++){const a=-Math.PI/2+i/n*Math.PI*1.75,b=-Math.PI/2+(i+1)/n*Math.PI*1.75;put([{x:inner*Math.cos(a),y:inner*Math.sin(a)},{x:radius*Math.cos(a),y:radius*Math.sin(a)},{x:radius*Math.cos(b),y:radius*Math.sin(b)},{x:inner*Math.cos(b),y:inner*Math.sin(b)}])}}else{for(let i=0;i<n;i++)put(rectPoly(-w/2,-d/2+i*d/n,w/2,-d/2+(i+1)*d/n))}return out}
