export function moveVertex(p,l,s,index,q){if(!q||!Number.isFinite(q.x)||!Number.isFinite(q.y)||Math.abs(q.x)>1000||Math.abs(q.y)>1000)throw Error('Ungültiger Eckpunkt');const x=selectedEntity(p,l,s);if(!x)throw Error('Element fehlt');if(s.type==='wall'){if(index!==0&&index!==1)throw Error('Ungültiges Wandende');const previous=rooms(l),oldSettings=l.roomSettings||{};editWall(l,x,{[index===0?'a':'b']:{...q}});const next=rooms(l);for(const r of previous){const meta=oldSettings[r.id];if(!meta||next.some(n=>n.id===r.id))continue;const matches=next.filter(n=>n.boundaryKey===r.boundaryKey);if(matches.length===1){(l.roomSettings??={})[matches[0].id]=meta;delete l.roomSettings[r.id]}}}else if(['parcel','landscape','roofpatch','route'].includes(s.type)){if(!x.points[index])throw Error('Eckpunkt fehlt');const pts=x.points.map((v,i)=>i===index?{...v,...q}:v);if(s.type!=='route'&&!polygonValid(pts))throw Error('Fläche würde sich überschneiden oder wäre zu klein');if(s.type==='route'&&pts.some((v,i)=>i&&dist(v,pts[i-1])<.02))throw Error('Leitung wäre zu kurz');if(s.type==='parcel')p.parcel={points:pts};else x.points=pts}else throw Error('Keine bearbeitbaren Eckpunkte')}
export function magnetPoint(l,p,raw,threshold,{excludePoint,excludeObject,excludeSelection,axes=true}={}){const pts=[];for(const w of l.walls){pts.push(w.a,w.b,{x:(w.a.x+w.b.x)/2,y:(w.a.y+w.b.y)/2})}for(const o of l.objects){if(o.id!==excludeObject)pts.push({x:o.x,y:o.y},...footprint(o))}for(const a of [p.parcel,...(p.landscape||[])].filter(Boolean)){if(excludeSelection&&(excludeSelection.type==='parcel'&&a===p.parcel||excludeSelection.type==='landscape'&&a.id===excludeSelection.id))continue;pts.push(...a.points)}const candidates=pts.filter(q=>!excludePoint||dist(q,excludePoint)>1e-5);let point=null,best=threshold;for(const q of candidates){const d=dist(q,raw);if(d<best){best=d;point=q}}if(point)return {point:{...point},guides:[{axis:'x',value:point.x},{axis:'y',value:point.y}],kind:'Punkt'};if(!axes)return null;let x=null,y=null,dx=threshold,dy=threshold;for(const q of candidates){if(Math.abs(q.x-raw.x)<dx){dx=Math.abs(q.x-raw.x);x=q.x}if(Math.abs(q.y-raw.y)<dy){dy=Math.abs(q.y-raw.y);y=q.y}}if(x===null&&y===null)return null;return {point:{x:x??raw.x,y:y??raw.y},guides:[...(x===null?[]:[{axis:'x',value:x}]),...(y===null?[]:[{axis:'y',value:y}])],kind:'Ausrichtung'}}
export function magnetObject(l,p,o,raw,threshold){const probe={...o,...raw},points=[{x:raw.x,y:raw.y},...footprint(probe)];let x=0,y=0,bx=threshold,by=threshold,gx=null,gy=null;for(const q of points){const hit=magnetPoint(l,p,q,threshold,{excludeObject:o.id});if(!hit)continue;for(const g of hit.guides){const delta=g.value-q[g.axis];if(g.axis==='x'&&Math.abs(delta)<bx){x=delta;bx=Math.abs(delta);gx=g}if(g.axis==='y'&&Math.abs(delta)<by){y=delta;by=Math.abs(delta);gy=g}}}return {point:{x:raw.x+x,y:raw.y+y},guides:[gx,gy].filter(Boolean)}}
export function selectedEntity(p,l,s){if(!s)return null;const {type,id,parent}=s;return type==='wall'?l.walls.find(w=>w.id===id):type==='object'?l.objects.find(o=>o.id===id):type==='opening'?l.walls.find(w=>w.id===parent)?.openings.find(o=>o.id===id):type==='room'?rooms(l).find(r=>r.id===id):type==='parcel'?p.parcel:type==='landscape'?p.landscape?.find(o=>o.id===id):type==='route'?l.routes?.find(o=>o.id===id):type==='roofpatch'?p.roofPatches?.find(o=>o.id===id):null}
